"""Builds departure boards from a timetable feed. See /app/docs."""
import csv
import io
import json
import os
import sys
from collections import defaultdict
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read_csv(directory, name):
    path = os.path.join(directory, name)
    if not os.path.exists(path):
        return []
    with open(path, "rb") as f:
        text = f.read().decode("utf-8")
    if text.startswith("\ufeff"):
        text = text[1:]
    reader = csv.reader(io.StringIO(text, newline=""))
    header = None
    rows = []
    for raw in reader:
        if not raw or all(not c.strip() for c in raw):
            continue
        if header is None:
            header = [c.strip() for c in raw]
            continue
        row = {}
        for i, h in enumerate(header):
            row[h] = raw[i].strip() if i < len(raw) else ""
        rows.append(row)
    return rows


def parse_time(s):
    h, m, sec = s.strip().split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def parse_date(s):
    s = s.strip()
    return date(int(s[0:4]), int(s[4:6]), int(s[6:8]))


_tz_cache = {}


def tz(name):
    if name not in _tz_cache:
        _tz_cache[name] = ZoneInfo(name)
    return _tz_cache[name]


def origin(d, tzname):
    noon = datetime(d.year, d.month, d.day, 12, 0, 0, tzinfo=tz(tzname))
    return noon.astimezone(timezone.utc) - timedelta(hours=12)


def fmt(instant, tzname):
    local = instant.astimezone(tz(tzname))
    off = local.utcoffset()
    total = int(off.total_seconds())
    sign = "+" if total >= 0 else "-"
    total = abs(total)
    return local.strftime("%Y-%m-%dT%H:%M:%S") + "%s%02d:%02d" % (sign, total // 3600, total % 3600 // 60)


def service_runs(service_id, d, calendar, exceptions):
    ex = exceptions.get((service_id, d))
    if ex == 1:
        return True
    if ex == 2:
        return False
    row = calendar.get(service_id)
    if row is None:
        return False
    if not (row["start"] <= d <= row["end"]):
        return False
    return row["days"][d.weekday()] == 1


def main(indir, outfile):
    agencies = read_csv(indir, "agency.txt")
    stops = {r["stop_id"]: r for r in read_csv(indir, "stops.txt")}
    routes = {r["route_id"]: r for r in read_csv(indir, "routes.txt")}
    trips = {r["trip_id"]: r for r in read_csv(indir, "trips.txt")}
    agency_tz = {r["agency_id"]: r["agency_timezone"] for r in agencies}
    first_agency = agencies[0]
    default_tz = first_agency["agency_timezone"]

    calendar = {}
    for r in read_csv(indir, "calendar.txt"):
        days = [int(r[k] or 0) for k in ("monday", "tuesday", "wednesday", "thursday",
                                          "friday", "saturday", "sunday")]
        calendar[r["service_id"]] = {"days": days, "start": parse_date(r["start_date"]),
                                     "end": parse_date(r["end_date"])}
    exceptions = {}
    for r in read_csv(indir, "calendar_dates.txt"):
        try:
            exceptions[(r["service_id"], parse_date(r["date"]))] = int(r["exception_type"])
        except ValueError:
            pass

    freqs = defaultdict(list)
    for r in read_csv(indir, "frequencies.txt"):
        freqs[r["trip_id"]].append((parse_time(r["start_time"]), parse_time(r["end_time"]),
                                    int(r["headway_secs"]), int(r["exact_times"] or 0)))

    st_by_trip = defaultdict(list)
    for r in read_csv(indir, "stop_times.txt"):
        st_by_trip[r["trip_id"]].append(r)

    with open(os.path.join(indir, "request.json"), encoding="utf-8-sig") as f:
        request = json.load(f)
    dates = sorted({date.fromisoformat(s) for s in request["service_dates"]})

    # board stops
    def is_board_stop(s):
        lt = s.get("location_type", "") or "0"
        if lt == "1":
            return True
        return lt == "0" and not s.get("parent_station", "")

    def board_of(stop_id):
        s = stops[stop_id]
        p = s.get("parent_station", "")
        return p if p else stop_id

    board_tz = {}
    for sid, s in stops.items():
        if is_board_stop(s):
            board_tz[sid] = s.get("stop_timezone", "") or default_tz

    # Precompute per trip: ordered stop info (independent of date)
    trip_info = {}
    for tid, rows in st_by_trip.items():
        if tid not in trips:
            continue
        rows = sorted(rows, key=lambda r: int(r["stop_sequence"]))
        n = len(rows)
        times = []
        for r in rows:
            t = r.get("departure_time", "") or r.get("arrival_time", "")
            times.append(parse_time(t) if t else None)
        known = [i for i, t in enumerate(times) if t is not None]
        for a, b in zip(known, known[1:]):
            for i in range(a + 1, b):
                times[i] = times[a] + (times[b] - times[a]) * (i - a) // (b - a)
        trip = trips[tid]
        route = routes[trip["route_id"]]
        label = route.get("route_short_name", "") or route.get("route_long_name", "")
        last_stop = stops[rows[-1]["stop_id"]]
        parent = last_stop.get("parent_station", "")
        last_name = stops[parent]["stop_name"] if parent and parent in stops else last_stop["stop_name"]
        deps = []
        for i, r in enumerate(rows):
            if i == n - 1 or r.get("pickup_type", "") == "1":
                continue
            headsign = r.get("stop_headsign", "") or trip.get("trip_headsign", "") or last_name
            st = stops[r["stop_id"]]
            deps.append((i, times[i], headsign, st.get("platform_code", "") or None,
                         board_of(r["stop_id"])))
        trip_info[tid] = (label, deps, times[0])

    boards = {}
    for d in dates:
        for sid in board_tz:
            boards[(sid, d)] = []

    for d in dates:
        origins = {}
        for tid, (label, deps, t0) in trip_info.items():
            trip = trips[tid]
            if not service_runs(trip["service_id"], d, calendar, exceptions):
                continue
            route = routes[trip["route_id"]]
            ag = route.get("agency_id", "") or first_agency["agency_id"]
            atz = agency_tz.get(ag, default_tz)
            if atz not in origins:
                origins[atz] = origin(d, atz)
            org = origins[atz]
            entries = []  # (time_secs, until_secs, headway, kind, dep)
            if tid in freqs:
                for (start, end, head, exact) in freqs[tid]:
                    starts = []
                    s = start
                    while s < end:
                        starts.append(s)
                        s += head
                    if not starts:
                        continue
                    for dep in deps:
                        off = dep[1] - t0
                        if exact == 1:
                            for s in starts:
                                entries.append((s + off, None, None, "scheduled", dep))
                        else:
                            entries.append((starts[0] + off, starts[-1] + off, head, "interval", dep))
            else:
                for dep in deps:
                    entries.append((dep[1], None, None, "scheduled", dep))
            for (ts, us, head, kind, dep) in entries:
                bs = dep[4]
                btz = board_tz[bs]
                inst = org + timedelta(seconds=ts)
                out = {
                    "kind": kind,
                    "time": fmt(inst, btz),
                    "until": fmt(org + timedelta(seconds=us), btz) if us is not None else None,
                    "headway_secs": head,
                    "route": label,
                    "headsign": dep[2],
                    "trip": tid,
                    "platform": dep[3],
                    "agency": ag,
                }
                key = (inst, label, dep[2], tid, dep[3] is not None, dep[3] or "")
                boards[(bs, d)].append((key, out))

    result = {"service_dates": [d.isoformat() for d in dates], "boards": []}
    for (sid, d) in sorted(boards, key=lambda k: (k[0], k[1])):
        items = sorted(boards[(sid, d)], key=lambda x: x[0])
        result["boards"].append({
            "stop_id": sid,
            "name": stops[sid]["stop_name"],
            "timezone": board_tz[sid],
            "service_date": d.isoformat(),
            "departures": [o for _, o in items],
        })
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
